INSERT INTO `ticket_categories` (`id`, `name`, `description`, `icon`, `color`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'HVAC (AC & Pendingin)', 'Khusus menangani pengaturan suhu udara dan mesin pendingin. Mencakup perawatan AC (Split/Cassette), kipas angin, exhaust fan, serta mesin pendingin makanan (Chiller, Freezer, Under counter).', 'Wind', '#06B6D4', 1, 0, '2026-01-28 03:18:56', '2026-01-28 03:18:56'),
(2, 'Electrical (ME - Kelistrikan)', 'Menangani seluruh instalasi arus listrik kuat dan lemah. Mencakup panel listrik (MCB), lampu penerangan, saklar, stop kontak, genset, dan kabel-kabel distribusi daya.', 'Zap', '#3B82F6', 1, 0, '2026-01-28 03:19:31', '2026-01-28 03:19:31'),
(3, 'Plumbing (Saluran Air)', 'Fokus pada sistem perpipaan air bersih dan air kotor. Mencakup perawatan pompa air, toren (tangki air), kran, wastafel, toilet, floor drain, dan penyaring lemak (Grease Trap).', 'Sparkles', '#EC4899', 1, 0, '2026-01-28 03:20:19', '2026-01-28 03:20:19'),
(4, 'Civil & Building (Sipil)', 'Perawatan fisik bangunan dan furnitur. Mencakup perbaikan dinding (cat/retak), lantai (keramik pecah), plafon bocor, pintu, kunci, engsel, serta meja dan kursi.', 'Tag', '#EF4444', 1, 0, '2026-01-28 03:21:31', '2026-01-28 03:21:31'),
(5, 'Kitchen Equipment (Peralatan Dapur)', 'Khusus untuk perawatan alat-alat masak komersial (Hot Kitchen). Mencakup kompor gas (Stove), penggorengan (Deep Fryer), panggangan, oven, dan saluran gas LPG.', NULL, '#8B5CF6', 1, 0, '2026-01-28 03:22:10', '2026-01-28 03:22:10'),
(6, 'Safety & Security (Keamanan)', 'Perawatan perangkat keselamatan kerja dan keamanan area. Mencakup pemeriksaan APAR (Alat Pemadam Api Ringan), sistem alarm, dan kamera pengawas (CCTV).', 'Shield', '#22C55E', 1, 0, '2026-01-28 03:23:12', '2026-01-28 03:23:12');
