INSERT INTO `whatsapp_templates` (`id`, `type`, `name`, `content`, `is_active`, `send_to_group`, `created_at`, `updated_at`) VALUES
(1, 'ticket_created', 'Tiket Baru (Group)', '🚨 *TIKET BARU DITERIMA* 🚨\n\nAda tiket baru masuk! Mohon segera dicek untuk ditentukan penanganannya.\n\n📋 *Kode:* {ticket_code}\n📝 *Judul:* {title}\n👤 *Pelapor:* {reporter_name}\n🏢 *Cabang:* {branch_name}\n⚡ *Prioritas:* {priority}\n📅 *Dibuat:* {created_at}\n\n📄 *Deskripsi:*\n{description}', 1, 1, '2026-02-25 18:00:12', '2026-02-25 18:00:12'),
(2, 'ticket_assigned', 'Tiket Ditugaskan (Staff)', 'Halo {staff_name},\n\nAnda telah ditugaskan untuk menangani tiket *{ticket_code}*.\nSilakan cek detail kendala dan mulai pengerjaan.\n\n📝 *Judul:* {title}\n👤 *Pelapor:* {reporter_name}\n🏢 *Cabang:* {branch_name}\n⚡ *Prioritas:* {priority}\n\n📄 *Deskripsi:*\n{description}', 1, 0, '2026-02-25 18:00:13', '2026-02-25 18:00:13'),
(3, 'ticket_status_progress', 'Status Progress (User)', 'Halo {reporter_name},\n\nKabar terbaru! Tiket Anda *{ticket_code}* saat ini sedang dalam proses pengerjaan oleh tim kami.\n\n📝 *Judul:* {title}\n📊 *Status:* {new_status}\n\nMohon ditunggu update selanjutnya.', 1, 0, '2026-02-25 18:00:13', '2026-02-25 18:00:13'),
(4, 'ticket_status_resolved', 'Status Resolved (User)', 'Halo {reporter_name},\n\nKabar baik! Kendala Anda pada tiket *{ticket_code}* sudah diperbaiki.\n\n📝 *Judul:* {title}\n📊 *Status:* {new_status}\n\nSilakan dicek kembali, jika sudah oke, tiket bisa ditutup.', 1, 0, '2026-02-25 18:00:13', '2026-02-25 18:00:13'),
(5, 'ticket_reply', 'Komentar Baru (User & Staff)', 'Ada komentar atau pesan baru di tiket *{ticket_code}*.\n\n💬 *Dari:* {replier_name}\n\n📄 *Pesan:*\n{reply_content}\n\nSilakan cek percakapan untuk informasi lebih lanjut.', 1, 0, '2026-02-25 18:00:13', '2026-02-25 18:00:13'),
(6, 'ticket_closed', 'Tiket Selesai (Group)', '✅ *LAPORAN SELESAI* ✅\n\nLaporan selesai. Tiket *{ticket_code}* telah resmi ditutup dan dianggap tuntas.\n\n📝 *Judul:* {title}\n👤 *Pelapor:* {reporter_name}\n🏢 *Cabang:* {branch_name}\n👨‍🔧 *Teknisi:* {staff_name}\n⏰ *Waktu Selesai:* {completed_at}\n\nTerima kasih atas kerja kerasnya!', 1, 1, '2026-02-25 18:00:13', '2026-02-25 18:00:13'),
(7, 'ticket_unassigned_user_alert', 'Alert Unassigned (User)', 'Halo {reporter_name},\n\nTiket Anda *{ticket_code}* belum mendapatkan penugasan teknisi. Mohon hubungi admin jika kendala ini sangat mendesak.\n\n📝 *Judul:* {title}\n🏢 *Cabang:* {branch_name}', 1, 0, '2026-02-25 18:00:13', '2026-02-25 18:00:13'),
(8, 'ticket_unassigned_admin_alert', 'Alert Unassigned (Admin)', '⚠️ *ALERT: TIKET BELUM DI-ASSIGN* ⚠️\n\nTiket *{ticket_code}* belum ditugaskan ke teknisi selama lebih dari 1 jam.\nMohon segera assign staff teknisi.\n\n📝 *Judul:* {title}\n👤 *Pelapor:* {reporter_name}\n🏢 *Cabang:* {branch_name}\n⚡ *Prioritas:* {priority}', 1, 1, '2026-02-25 18:00:13', '2026-02-25 18:00:13'),
(9, 'ticket_created_user', 'Tiket Diterima (User)', 'Halo {reporter_name}, 👋\n\nKami telah menerima tiket laporan Anda:\n📋 *Kode:* {ticket_code}\n📝 *Judul:* {title}\n\nTim kami akan segera menindaklanjuti laporan ini. Mohon ditunggu updatenya.\n\nTerima kasih.', 1, 0, '2026-02-25 18:00:13', '2026-02-25 18:00:13'),
(10, 'work_report_created', 'Laporan Kerja Baru (Group)', '📝 *LAPORAN KERJA BARU* 📝\n\nTeknisi baru saja mengirimkan laporan pekerjaan.\n\n👤 *Teknisi:* {staff_name}\n📋 *Tiket/SPK:* {ticket_code}\n🏢 *Cabang:* {branch_name}\n📊 *Status:* {status}\n\n📄 *Laporan:*\n{description}\n\n🔗 Silakan cek foto & detail di dashboard.', 1, 1, '2026-02-25 18:00:13', '2026-02-25 18:00:13'),
(11, 'work_order_completed_user', 'Pekerjaan Selesai (User)', 'Halo {reporter_name}, 👋\n\nPekerjaan untuk tiket *{ticket_code}* telah diselesaikan oleh teknisi kami.\n\n📝 *Judul:* {title}\n👨‍🔧 *Teknisi:* {staff_name}\n\nMohon periksa hasilnya. Jika sudah sesuai, tiket akan kami tutup.\n\nTerima kasih.', 1, 0, '2026-02-25 18:00:13', '2026-02-25 18:00:13'),
(12, 'sla_warning', 'SLA Warning (Admin)', '⚠️ *SLA WARNING* ⚠️\n\nTiket *{ticket_code}* dengan prioritas *{priority}* belum diselesaikan!\n\n⏰ *Dibuat:* {created_at}\n⏳ *Durasi:* Sudah berjalan > {duration_hours} jam\n📝 *Judul:* {title}\n👨‍🔧 *Teknisi:* {staff_name}\n\nMohon segera di-follow up!', 1, 1, '2026-02-25 18:00:13', '2026-02-25 18:00:13'),
(13, 'routine_maintenance_reminder', 'Reminder Maintenance (Staff)', '🔔 *REMINDER JADWAL RUTIN* 🔔\n\nHalo {staff_name},\nJangan lupa hari ini ada jadwal maintenance rutin:\n\n🔧 *Pekerjaan:* {job_name}\n🏢 *Cabang:* {branch_name}\n\nSilakan buat SPK/Laporan sesuai jadwal. Semangat! 💪', 1, 0, '2026-02-25 18:00:13', '2026-02-25 18:00:13');
